import {captureCalculation,RELEASE} from './material-notebook.js?v=20261031-entry1';
import {esc,num,table,notes,sources,defaultInputs,controlsHTML,readControls,resultHTML,bindResult} from './response-views.js?v=20261031-entry1';
import {renderResponseProjects} from './response-projects.js?v=20261031-entry1';
const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
const options=(rows,v)=>rows.map(([id,title])=>`<option value="${esc(id)}" ${String(id)===String(v)?'selected':''}>${esc(title)}</option>`).join('');
let catalogPromise,lastResult=null;
const catalog=()=>catalogPromise??=fetch('data/response-materials.json?v='+RELEASE).then(r=>{if(!r.ok)throw Error('横向响应、器件与多电子课程暂未载入');return r.json();}).catch(e=>{catalogPromise=null;throw e;});
export const getResponseMaterialsResult=()=>lastResult;
export const responseCourseRoute=(id,query='')=>'#classroom/'+({multiplet:'spin',device:'crystal',hall:'observables'}[id]||'spin')+'?module='+id+(query?'&'+query:'');
const select=(label,key,rows,value)=>`<label>${esc(label)}<select id="rp-${key}">${options(rows,value)}</select></label>`;
const defaults=defaultInputs;
export async function renderResponseMaterialsView({container,selection={},run,cancelRun,download,onNavigate=()=>{},onLocation=()=>{}}){
 container.innerHTML='<div class="obs-page qm-page response-page"><p role="status">正在准备横向响应、器件与多电子课程…</p></div>';
 const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;lastResult=null;
 let data;try{data=await catalog();}catch(e){if(current())root.innerHTML=`<p role="alert">${esc(e.message)}</p>`;return;}if(!current())return;
 let module=data.modules.find(m=>m.id===selection.module)||data.modules[0],lesson=data.lessons.find(l=>l.id===selection.lesson&&l.module===module.id)||data.lessons.find(l=>l.module===module.id),exercise=data.exercises.find(e=>e.id===selection.exercise&&e.module===module.id)||data.exercises.find(e=>e.lesson===lesson.id),tab=selection.calculationOnly?'lab':selection.atlasOnly?'cases':['learn','lab','derive','cases','project'].includes(selection.tab)?selection.tab:'learn';
 if(selection.exercise)lesson=data.lessons.find(l=>l.id===exercise.lesson)||lesson;
 const forms=structuredClone(defaults),material=data.cases.find(c=>c.id===selection.material&&c.module===module.id);let preset=selection.preset||material?.preset||'';
 const applyPreset=id=>{const p=module.presets.find(p=>p.id===id);if(p){forms[module.id]={...structuredClone(defaults[module.id]),...structuredClone(p.input)};if(p.input.data)forms[module.id].content=JSON.stringify(p.input.data,null,2);preset=p.id;}};applyPreset(preset);
 let result=null,busy=false,ticket=0,progress={};try{const p=JSON.parse(localStorage.getItem('symmetry-lab.response-materials.progress.v1')||'{}');if(object(p))progress=p;}catch{}
 const sync=()=>onNavigate({module:module.id,tab,lesson:lesson.id,exercise:tab==='derive'?exercise.id:undefined,material:selection.material,preset});
 const context=()=>new URLSearchParams({module:module.id,...(selection.material?{material:selection.material}:{}),...(preset?{preset}:{})}).toString();
 const links=()=>`<div class="obs-links"><a href="${responseCourseRoute(module.id,(selection.material?'material='+encodeURIComponent(selection.material)+'&':'')+(preset?'preset='+encodeURIComponent(preset):''))}">课程与推导 →</a><a href="#atlas/response?${esc(context())}">材料与模型案例 →</a><a href="#atlas/projects?module=${module.id}">跨模块项目作业 →</a><a href="#atlas/notebook">保存材料研究记录 →</a></div>`;
 function invalidate(message='参数已改变，请运行计算以更新图形。'){ticket++;result=null;lastResult=null;if(busy){cancelRun?.();busy=false;}if($('#rp-result'))$('#rp-result').innerHTML=`<p role="status">${esc(message)}</p>`;if($('#rp-run'))$('#rp-run').disabled=false;}
 function draw(){if(!current())return;onLocation((selection.calculationOnly?'计算中心 / ':selection.atlasOnly?'群与材料图谱 / ':'学习中心 / ')+module.title);root.innerHTML=`<header class="obs-header"><span class="obs-eyebrow">RESPONSE · DEVICES · MULTIPLETS</span><h2>${selection.atlasOnly?'从对称性走到横向响应、器件与多电子信号':esc(module.title)}</h2><p>${selection.atlasOnly?'真实材料背景与可验证教学模型相互连接。':esc(module.summary)}</p></header>${selection.calculationOnly||selection.atlasOnly?'':`<nav class="obs-tabs" aria-label="横向响应、器件与多电子课堂">${[['learn','课程讲解'],['lab','交互实验'],['derive','分步练习'],['cases','材料案例'],['project','项目作业']].map(([id,t])=>`<button type="button" data-rp-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${t}</button>`).join('')}</nav>`}<div id="rp-content"></div>`;root.querySelectorAll('[data-rp-tab]').forEach(b=>b.onclick=()=>{invalidate();tab=b.dataset.rpTab;draw();sync();});if(tab==='learn')learn();else if(tab==='derive')derive();else if(tab==='cases')cases();else if(tab==='project')renderResponseProjects({container:$('#rp-content'),selection:{project:selection.project,module:module.id},download});else lab();}
 function learn(){$('#rp-content').innerHTML=`${select('选择主题','lesson',data.lessons.filter(l=>l.module===module.id).map(l=>[l.id,l.title]),lesson.id)}<article class="obs-lesson"><h2>${esc(lesson.title)}</h2><p class="obs-lead">${esc(lesson.summary)}</p>${lesson.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.formula?`<div class="obs-formula">${esc(s.formula)}</div>`:''}</section>`).join('')}<div class="obs-links"><button id="rp-to-lab" class="primary">打开对应实验 →</button><button id="rp-to-derive" class="secondary">分步推导 →</button></div>${links()}${sources(data.sources.filter(s=>lesson.references.includes(s.id)))}</article>`;$('#rp-lesson').onchange=e=>{lesson=data.lessons.find(l=>l.id===e.target.value);exercise=data.exercises.find(e=>e.lesson===lesson.id);draw();sync();};$('#rp-to-lab').onclick=()=>{applyPreset(lesson.preset);invalidate();tab='lab';draw();sync();};$('#rp-to-derive').onclick=()=>{exercise=data.exercises.find(e=>e.lesson===lesson.id);tab='derive';draw();sync();};}
 function cases(){$('#rp-content').innerHTML=`<div class="obs-case-grid">${data.cases.filter(c=>selection.atlasOnly||c.module===module.id).sort((a,b)=>(b.id===selection.material)-(a.id===selection.material)).map(c=>{const m=data.modules.find(m=>m.id===c.module),q=new URLSearchParams({material:c.id,preset:c.preset}).toString();return `<article><span class="obs-eyebrow">${esc(c.kind)}</span><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p>${notes([c.assumption])}<div class="obs-links"><a href="${responseCourseRoute(c.module,q)}">学习与推导 →</a><a href="#compute/${m.route}?${q}">打开对应计算 →</a>${c.links.filter(([,url])=>url!=='#atlas/notebook').map(([title,url])=>`<a href="${esc(url)}">${esc(title)} →</a>`).join('')}<a href="#atlas/notebook">研究记录 →</a></div></article>`;}).join('')}</div>`;}
 function derive(){let step=0;const list=data.exercises.filter(e=>e.module===module.id);$('#rp-content').innerHTML=`${select('选择分步练习','exercise',list.map(e=>[e.id,(progress[e.id]?'✓ ':'')+e.title]),exercise.id)}<article class="obs-lesson"><h2>${esc(exercise.title)}</h2><p>${esc(exercise.prompt)}</p><div id="rp-steps"></div><p id="rp-progress" role="status"></p>${links()}</article>`;$('#rp-exercise').onchange=e=>{exercise=list.find(x=>x.id===e.target.value);lesson=data.lessons.find(l=>l.id===exercise.lesson);draw();sync();};function next(){const s=exercise.steps[step],el=document.createElement('section');el.className='obs-exercise-step';el.innerHTML=`<h3>第 ${step+1} / ${exercise.steps.length} 步</h3><p>${esc(s.prompt)}</p><details><summary>查看提示</summary><p>${esc(s.hint)}</p></details><div class="mr-choices">${s.choices.map((c,i)=>`<button type="button" class="secondary" data-rp-answer="${i}">${esc(c)}</button>`).join('')}</div><p class="obs-feedback" role="status"></p>`;$('#rp-steps').appendChild(el);el.querySelectorAll('[data-rp-answer]').forEach(b=>b.onclick=()=>{if(+b.dataset.rpAnswer!==s.answer){el.querySelector('.obs-feedback').textContent='再想一想：'+s.hint;return;}el.querySelector('.obs-feedback').textContent='✓ '+s.explanation;el.querySelectorAll('button').forEach(b=>b.disabled=true);step++;if(step<exercise.steps.length)next();else{progress[exercise.id]=true;try{localStorage.setItem('symmetry-lab.response-materials.progress.v1',JSON.stringify(progress));}catch{}$('#rp-progress').textContent='✓ 推导完成。请到实验中改变参数，检验这个结论。';}});}next();}

 function lab(){
  $('#rp-content').innerHTML=`<div class="qm-lab"><form id="rp-form" class="obs-controls">${select('教学预设','preset',[['','自定义 / 当前参数'],...module.presets.map(p=>[p.id,p.title])],preset)}${controlsHTML(module.id,forms[module.id])}<button id="rp-run" type="submit" class="primary">计算并更新演示</button><button id="rp-cancel" type="button" class="secondary">取消计算</button><p id="rp-status" role="status">Python 在浏览器本地运行。</p></form><section id="rp-result" class="qm-results" aria-live="polite"><div class="qm-welcome"><h3>从一个预设开始</h3><p>调整参数，比较物理响应与数值校验，再把结果收录到项目作业。</p></div></section></div>${links()}`;
  const form=$('#rp-form');form.onsubmit=e=>{e.preventDefault();calculate();};
  form.oninput=e=>{if(e.target.id==='rp-preset')return;invalidate();
   if(module.id==='device'&&['rp-sites','rp-barrierStart'].includes(e.target.id)){
    const count=Number($('#rp-sites').value);if(Number.isInteger(count)&&count>=2&&count<=40){
     const start=$('#rp-barrierStart'),width=$('#rp-barrierWidth');start.max=count-1;start.value=Math.min(Number(start.value),count-1);width.max=count-Number(start.value);width.value=Math.min(Number(width.value),Number(width.max));
    }
   }
   try{forms[module.id]=readControls(module.id,root,forms[module.id]);}catch{}preset='';$('#rp-preset').value='';
  };
  $('#rp-preset').onchange=e=>{invalidate();applyPreset(e.target.value);draw();sync();};
  $('#rp-cancel').onclick=()=>{invalidate('计算已取消，可以修改参数后重新运行。');$('#rp-status').textContent='已取消';};
  if(result)renderResult();
 }
 async function calculate(){if(busy)return;let input;
  try{input=structuredClone(readControls(module.id,root,forms[module.id]));forms[module.id]=structuredClone(input);}catch(e){$('#rp-result').textContent=e.message;return;}
  const id=++ticket;busy=true;result=null;lastResult=null;$('#rp-run').disabled=true;$('#rp-status').textContent='正在计算…';$('#rp-result').innerHTML='<p role="status">正在运行 Python 并检查数值结果…</p>';
  try{const output=await run(module.action,input);if(!current()||id!==ticket||tab!=='lab')return;result=output;lastResult={module:module.id,input:structuredClone(input),result:output};
   const route=selection.calculationOnly?'compute/'+module.route+(context()?'?'+context():''):responseCourseRoute(module.id).slice(1);captureCalculation(module.action,input,output,{route,title:module.title,material:selection.material||''});
   $('#rp-status').textContent='计算完成 · 可导出或收录到项目作业';renderResult();
  }catch(e){if(current()&&id===ticket){$('#rp-result').textContent=e.message;$('#rp-status').textContent='计算未完成，请检查参数';}}
  finally{if(current()&&id===ticket){busy=false;if($('#rp-run'))$('#rp-run').disabled=false;}}
 }
 function renderResult(){$('#rp-result').innerHTML=`<div class="qm-result-heading"><span class="tag">浏览器 Python 结果</span><button id="rp-export" type="button" class="secondary">导出完整 JSON</button></div>${resultHTML(module.id,result)}<a href="#atlas/projects?module=${module.id}">收录计算到跨模块项目 →</a>`;bindResult(module.id,result,root);$('#rp-export').onclick=()=>download?.(JSON.stringify(lastResult,null,2),module.id+'-result.json','application/json');}
 draw();
}
